/**
 * Knob: `paired-control` (G2, jun-24 scaffold SOTA absorption). Tightens the
 * repro-test ADMISSION filter so a self-authored symptom test is admitted as a
 * bug-reproducer ONLY when its PAIRED CONTROL tests (happy-path / edge cases,
 * generated by the SAME repro-gen, NEVER the gold) PASS on the BASE tree.
 *
 * GAP (`src/agent/repro-test/select.ts`): the legacy filter keeps every sample
 * whose `outcome === "reproduced"` — a base-RED self-test. But a base-RED can be
 * a FALSE-RED: the project failed to import / the exec env is broken, so the
 * symptom test fails for a reason unrelated to the issue (the astropy-13033
 * shape — a self-authored test admitted on a broken base). The filter cannot
 * tell a real base-FAIL from an env/import-broken base-FAIL.
 *
 * G2: pair each symptom test with control tests that SHOULD pass on base in a
 * healthy env. The control verdict (`baseControl`) certifies the env:
 *   - controls GREEN ⇒ env healthy ⇒ a base-RED symptom is a REAL reproduction.
 *   - controls RED   ⇒ env/import broken ⇒ the symptom's base-RED is a FALSE-RED.
 * The admission predicate becomes `reproduced && baseControl === "green"`;
 * everything else (red / absent) is fail-closed rejected.
 *
 * Default-OFF. NOOP-apply registry entry: the EFFECT is delivered out of band by
 * the bench driver via `benchPostureFromState` projection (`pairedControl`
 * field), which threads the gate into `selectReproTest`'s `pairedControl` option
 * — the single reader site that branches admission on `baseControl`. The control
 * tests are produced by the EXISTING repro-gen path (public issue/repo only),
 * never the gold. Strict truthy gate: `"1"`/`"on"`/`"true"` ⇒ enabled. A losing
 * knob is deleted, not left as a permanent research flag.
 */

import type { AgentConfig } from "@/agent"
import { registerKnob } from "../registry"
import type { Knob, Surface } from "../types"

const SURFACES: readonly Surface[] = ["bench"]
const ENABLING = new Set(["1", "on", "true"])

const parsePairedControl = (raw: string | undefined): true | undefined => {
  if (raw === undefined) return undefined
  return ENABLING.has(raw.trim().toLowerCase()) ? true : undefined
}

const applyPairedControl = (cfg: AgentConfig): AgentConfig => cfg

export const pairedControlKnob: Knob<true> = {
  id: "paired-control",
  envKey: "QUANTA_BENCH_PAIRED_CONTROL",
  category: "tool",
  surfaces: SURFACES,
  parse: parsePairedControl,
  apply: applyPairedControl,
  describe:
    "G2 paired-control: admit a reproducing self-test only when its paired control tests (happy/edge, same repro-gen, never gold) pass on the base tree — rejects env/import-broken false-reds at the repro admission filter",
  source: "jun-24 scaffold SOTA absorption plan (G2)",
}

registerKnob(pairedControlKnob)
